cssOverrides:
/* Design Lab Eastbourne – site-specific overrides */

:root {
  --color-brand-primary: var(--color-brand-primary);
  --nav-height: 64px;
  --section-padding-y: 4rem;
}

body {
  background-color: var(--color-surface-background);
  color: var(--color-surface-foreground);
  font-family: var(--font-sans);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: var(--font-weight-heading);
  color: var(--color-surface-foreground);
}

a {
  color: var(--color-brand-primary);
}

a:hover {
  color: var(--color-brand-primary-hover);
}

.btn-primary {
  background-color: var(--color-brand-primary);
  color: var(--color-brand-on-primary);
  border-radius: var(--radius-button);
  font-weight: 700;
}

.btn-primary:hover {
  background-color: var(--color-brand-primary-hover);
}

.btn-outline-white {
  background-color: transparent;
  color: var(--color-surface-foreground);
  border: 2px solid var(--color-surface-foreground);
  border-radius: var(--radius-button);
  font-weight: 700;
}

.btn-outline-white:hover {
  background-color: var(--color-surface-foreground);
  color: var(--color-surface-background);
}

.cta-banner {
  background-color: var(--color-brand-primary);
  color: var(--color-brand-on-primary);
}

.card {
  background-color: var(--color-surface-card);
  border-color: var(--color-surface-card-border);
  border-radius: var(--radius-card);
  color: var(--color-surface-foreground);
}

.section-dark {
  background-color: var(--color-surface-background);
  color: var(--color-surface-foreground);
}

.section-muted {
  background-color: var(--color-surface-muted);
  color: var(--color-surface-muted-foreground);
}

.text-brand {
  color: var(--color-brand-primary);
}

.footer {
  background-color: var(--color-surface-inverse);
  color: var(--color-surface-foreground);
}

.hero-image-frame {
  border: 3px solid var(--color-brand-primary);
  border-radius: var(--radius-card);
}

.eyebrow-label {
  color: var(--color-brand-primary);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.nav-bar {
  background-color: var(--color-surface-background);
  color: var(--color-surface-foreground);
  height: var(--nav-height);
}

.section {
  padding-top: var(--section-padding-y);
  padding-bottom: var(--section-padding-y);
}
